import type { Part } from '@google/genai';
import type { ContentPart } from './types.js';
import type { ToolResultDisplay } from '../tools/tools.js';

/**
 * Converts an array of Gemini {@link Part}s into the internal
 * {@link ContentPart} representation.
 *
 * - Text parts become `text` content parts.
 * - Thought parts become `thought` content parts (preserving the signature).
 * - `inlineData` parts become `media` content parts with inline `data`.
 * - `fileData` parts become `media` content parts referencing a `uri`.
 * - `functionCall` / `functionResponse` parts are dropped, as they are not
 *   representable as displayable content.
 * - Anything else is serialized to a `text` part and flagged via `_meta`.
 */
export function geminiPartsToContentParts(parts: Part[]): ContentPart[] {
  const result: ContentPart[] = [];

  for (const part of parts) {
    if (part.thought) {
      const thought: ContentPart = {
        type: 'thought',
        thought: part.text ?? '',
      };
      if (part.thoughtSignature !== undefined) {
        thought.thoughtSignature = part.thoughtSignature;
      }
      result.push(thought);
    } else if (part.text !== undefined) {
      result.push({ type: 'text', text: part.text });
    } else if (part.inlineData) {
      result.push({
        type: 'media',
        data: part.inlineData.data,
        mimeType: part.inlineData.mimeType,
      });
    } else if (part.fileData) {
      result.push({
        type: 'media',
        uri: part.fileData.fileUri,
        mimeType: part.fileData.mimeType,
      });
    } else if (part.functionCall || part.functionResponse) {
      // Function calls/responses are handled elsewhere and have no direct
      // content representation.
      continue;
    } else {
      result.push({
        type: 'text',
        text: JSON.stringify(part),
        _meta: { unknown: true },
      });
    }
  }

  return result;
}

/**
 * Converts an array of internal {@link ContentPart}s back into Gemini
 * {@link Part}s.
 *
 * - `text` parts become Gemini text parts.
 * - `thought` parts become Gemini text parts flagged with `thought: true`.
 * - `media` parts with `data` become `inlineData` parts.
 * - `media` parts with `uri` become `fileData` parts.
 * - `media` parts with neither `data` nor `uri` are dropped.
 * - Any other variant is serialized to a Gemini text part.
 */
export function contentPartsToGeminiParts(parts: ContentPart[]): Part[] {
  const result: Part[] = [];

  for (const part of parts) {
    switch (part.type) {
      case 'text':
        result.push({ text: part.text });
        break;
      case 'thought': {
        const geminiPart: Part = { text: part.thought, thought: true };
        if (part.thoughtSignature !== undefined) {
          geminiPart.thoughtSignature = part.thoughtSignature;
        }
        result.push(geminiPart);
        break;
      }
      case 'media':
        if (part.data !== undefined) {
          result.push({
            inlineData: {
              data: part.data,
              mimeType: part.mimeType ?? 'application/octet-stream',
            },
          });
        } else if (part.uri !== undefined) {
          result.push({
            fileData: {
              fileUri: part.uri,
              mimeType: part.mimeType,
            },
          });
        }
        // Media parts with neither data nor uri are skipped.
        break;
      default:
        result.push({ text: JSON.stringify(part) });
        break;
    }
  }

  return result;
}

/**
 * Normalizes a tool's display value into an array of {@link ContentPart}s.
 *
 * - `undefined` / `null` yields `undefined`.
 * - Strings are wrapped as a single `text` part.
 * - Objects are JSON-serialized into a single `text` part.
 */
export function toolResultDisplayToContentParts(
  value: ToolResultDisplay | undefined | null,
): ContentPart[] | undefined {
  if (value === undefined || value === null) {
